// The component harness, browser-safe half: the config schema and the address
// the canvas frames. No filesystem here (the canvas imports this file); the
// writing of config and generated files lives in server/harness.js.
import { isAllowedLiveUrl, propsProblem } from './storeCore.js';

export const HARNESS_CONFIG_FILE = 'klose.config.json';
export const REGISTRY_FILE = 'klose.registry.ts';
export const FRAMEWORKS = ['expo', 'vite'];
export const DEFAULT_HARNESS_PATH = '/__klose';
export const DEFAULT_EXPO_DEV_SERVER = 'http://localhost:8081';
export const DEFAULT_VITE_DEV_SERVER = 'http://localhost:5173';
/**
 * `server: "klose"` (Vite only): Klose starts a Vite server of its own and
 * writes nothing to the repo (server/harnessVite.js). Without it, the repo's
 * own dev server serves files Klose generates (server/harness.js).
 */
export const HARNESS_SERVERS = ['repo', 'klose'];
/** Where sketches are written so the repo's bundler can draw them (`sketchDir` in klose.config.json). */
export const DEFAULT_SKETCH_DIR = 'klose.sketches';

/** Header on every generated file. `init` and `sync` only overwrite files that still carry it. */
export const GENERATED_HEADER = '// generated by klose, do not edit (regenerate with `klose harness sync`)';

/**
 * Validate a parsed klose.config.json. Returns `{ config }` with defaults
 * filled in, or `{ error }`.
 */
export function validateHarnessConfig(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return { error: 'klose.config.json must be a JSON object' };
  const { framework, harnessPath = DEFAULT_HARNESS_PATH, providers, components, sketchDir, server } = raw;
  let { devServer } = raw;
  if (!FRAMEWORKS.includes(framework)) return { error: `framework must be one of: ${FRAMEWORKS.join(', ')}` };
  if (server !== undefined && !HARNESS_SERVERS.includes(server)) return { error: `server must be one of: ${HARNESS_SERVERS.join(', ')}` };
  const managed = server === 'klose';
  if (managed && framework !== 'vite') return { error: 'server "klose" is only for Vite projects' };
  // Klose starts the server on a free port, so there is no address to configure; this is a placeholder until it does.
  if (managed && devServer === undefined) devServer = DEFAULT_VITE_DEV_SERVER;
  if (!isAllowedLiveUrl(devServer)) {
    return { error: `devServer must be http(s) on localhost, 127.0.0.1, [::1] or *.localhost, with no credentials: ${JSON.stringify(devServer)}` };
  }
  if (typeof harnessPath !== 'string' || !/^(\/[\w@()[\].-]+)+$/.test(harnessPath) || harnessPath.split('/').some((seg) => seg === '.' || seg === '..')) {
    return { error: `harnessPath must be a route path like "/__klose" or "/preview/components" (letters, digits, "_", "-", ".", no trailing "/"): ${JSON.stringify(harnessPath)}` };
  }
  if (providers !== undefined && (typeof providers !== 'string' || !providers.trim() || /^(\/|[a-z]+:)/i.test(providers) || providers.split(/[\\/]/).includes('..'))) {
    return { error: 'providers must be a module path inside the repo (relative, no ".."), e.g. "src/Providers.tsx"' };
  }
  if (components !== undefined) {
    if (!Array.isArray(components) || !components.every((c) => typeof c === 'string' && c.includes('#') && isRepoRelative(c.split('#')[0]))) {
      return { error: 'components must be a list of "<file>#<export>" strings with repo-relative files' };
    }
  }
  if (sketchDir !== undefined && (typeof sketchDir !== 'string' || !/^[\w@.-]+(\/[\w@.-]+)*$/.test(sketchDir) || sketchDir.split('/').some((seg) => seg === '.' || seg === '..'))) {
    return { error: 'sketchDir must be a folder inside the repo (relative, no ".."), e.g. "klose.sketches" or "src/klose.sketches"' };
  }
  const config = { framework, devServer: devServer.replace(/\/+$/, ''), harnessPath };
  if (sketchDir !== undefined) config.sketchDir = sketchDir;
  if (managed) config.server = 'klose';
  if (providers !== undefined) config.providers = providers;
  if (components !== undefined) config.components = components;
  return { config };
}

function isRepoRelative(file) {
  return !!file && !/^(\/|[a-z]+:)/i.test(file) && !file.includes('\\') && !file.split('/').includes('..');
}

/** The registry key for a built component: `<file>#<export>`; the export defaults to `default`. */
export function registryKey(file, exportName) {
  return `${String(file).replace(/^\.\//, '')}#${exportName || 'default'}`;
}

function toBase64(text) {
  if (typeof Buffer !== 'undefined') return Buffer.from(text, 'utf-8').toString('base64');
  const bytes = new TextEncoder().encode(text);
  let bin = '';
  for (const b of bytes) bin += String.fromCharCode(b);
  return btoa(bin);
}

/** A sketch's id is part of a file name, so only plain ones get a file. */
const SKETCH_ID = /^[A-Za-z0-9][\w-]{0,63}$/;

/**
 * The file a sketch is written to for the repo's bundler (repo-relative), or
 * null when this node isn't one that gets a file: a built card renders its
 * real file, a live card its page, and a card without code has nothing to draw.
 */
export function sketchFile(config, node) {
  if (!config || !node || node.status === 'built' || node.url) return null;
  if (typeof node.code !== 'string' || !node.code.trim() || typeof node.id !== 'string' || !SKETCH_ID.test(node.id)) return null;
  return `${config.sketchDir || DEFAULT_SKETCH_DIR}/${node.id}.tsx`;
}

/** The registry key a card is rendered by: its built file, or the file its sketch was written to. */
export function harnessKey(config, node) {
  if (!config || !node) return null;
  if (node.status === 'built') return node.builtFilePath ? registryKey(node.builtFilePath, node.exportName) : null;
  const file = sketchFile(config, node);
  return file ? registryKey(file, node.exportName) : null;
}

/**
 * `<devServer><harnessPath>?c=<file>#<export>&props=<base64 json>` — the
 * address a card is framed at: a built card's real component, or a sketch that
 * was written into the repo (see `sketchFile`). The file lives in the query, the export
 * and props in the fragment (so the dev server never sees them). Null when the
 * config is unusable or the component isn't in the registry.
 */
export function harnessAddress(config, node, registry) {
  const key = harnessKey(config, node);
  if (!key || !Array.isArray(registry) || !registry.includes(key)) return null;
  const [file, exp] = key.split('#');
  let address = `${config.devServer}${config.harnessPath}?c=${encodeURIComponent(file)}#${encodeURIComponent(exp)}`;
  if (node.props && Object.keys(node.props).length && !propsProblem(node.props)) {
    address += `&props=${encodeURIComponent(toBase64(JSON.stringify(node.props)))}`;
  }
  return isAllowedLiveUrl(address) ? address : null;
}
